CREATE TABLE sys_role(role_id BIGINT PRIMARY KEY,role_name VARCHAR(60) NOT NULL,role_key VARCHAR(60) NOT NULL UNIQUE,status CHAR(1) NOT NULL DEFAULT '0') ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE sys_user(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_name VARCHAR(100) NOT NULL UNIQUE,nick_name VARCHAR(60) NOT NULL,password VARCHAR(100) NOT NULL,role_id BIGINT NOT NULL,status CHAR(1) NOT NULL DEFAULT '0',auth_version BIGINT NOT NULL DEFAULT 0,totp_secret VARCHAR(255) NULL,create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_user_role FOREIGN KEY(role_id) REFERENCES sys_role(role_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE sys_menu(menu_id BIGINT PRIMARY KEY,parent_id BIGINT NOT NULL DEFAULT 0,menu_name VARCHAR(60) NOT NULL,path VARCHAR(100) NOT NULL DEFAULT '',menu_type CHAR(1) NOT NULL,perms VARCHAR(100),order_num INT NOT NULL DEFAULT 0,status CHAR(1) NOT NULL DEFAULT '0') ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE sys_role_menu(role_id BIGINT NOT NULL,menu_id BIGINT NOT NULL,PRIMARY KEY(role_id,menu_id),FOREIGN KEY(role_id) REFERENCES sys_role(role_id),FOREIGN KEY(menu_id) REFERENCES sys_menu(menu_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8;
CREATE TABLE sys_audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT NULL,action VARCHAR(60) NOT NULL,target VARCHAR(100),result VARCHAR(20) NOT NULL,create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8;
